    public double geometryReach(){if(reachAssembly!=assembly||reachColumns!=columns||reachPayload!=payload||reachView!=payloadView||reachSettings!=settings){reachAssembly=assembly;reachColumns=columns;reachPayload=payload;reachView=payloadView;reachSettings=settings;int height=assembly==null?1:assembly.columnHeight();double base=2*height+8+Math.abs(settings.activeExtension());reach=base;for(var column:columns)reach=Math.max(reach,base+distance(column));if(assembly!=null)for(var foot:assembly.feet())reach=Math.max(reach,base+Math.abs(foot.x)+Math.abs(foot.y)+Math.abs(foot.z));if(payloadView!=null){var frame=payloadView.reference();double offset=Math.abs(frame.tx())+Math.abs(frame.ty())+Math.abs(frame.tz());for(var cell:payloadView.cells())reach=Math.max(reach,base+offset+distance(cell.source())+3);}}return reach;}
